window.ZBORCEK_SONGBOOK = {"type":"zborcek-predstavitev","exportedAt":"2026-09-15T19:23:51.407Z","songs":[{"number":1,"title":"Aleluja Jubilate","body":"Aleluja Jubilate","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":1},{"number":2,"title":"Aleluja, naše veselje","body":"Alelu - aleluja,\nAlelu - aleluja,\nAlelu - aleluja,\nAleluja.\n\nNaše veselje ne bo se končalo,\nne bo se končalo in se ne konča.   (2x)","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":2},{"number":7,"title":"Darujem ti ljubezen","body":"Darujem Ti ljubezen, ki v meni živi,\nsprejmi ta dar, Gospod.\nTu je moja sreča, vse moje skrbi,\nvsak utrip srca darujem Ti.\n\nTi, Gospod, si v tem kruhu in vinu,\ntu tvoje je telo in tvoja kri.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":3},{"number":4,"title":"Če letal bi","body":"Če letal bi","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":4},{"number":5,"title":"Dal si čisto mi srce","body":"Dal si čisto mi srce,\ndal odprte mi roke,\ndal si čustva mi in dal si mi razum.\n\nZato bom vedno hodil za Teboj,\nzato bom vedno hodil za Teboj.\nEvangelij bom živel,\nalelujó Ti bom pel\nin vedno hodil za Teboj.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":5},{"number":6,"title":"Danes je dan","body":"Danes je dan","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":6},{"number":7,"title":"Darujem ti ljubezen","body":"Darujem Ti ljubezen, ki v meni živi,\nsprejmi ta dar, Gospod.\nTu je moja sreča, vse moje skrbi,\nvsak utrip srca darujem Ti.\n\nTi, Gospod, si v tem kruhu in vinu,\ntu tvoje je telo in tvoja kri.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":7},{"number":49,"title":"Ves dan vso noč","body":"Ves dan, vso noč\nangeli bdijo nad menoj, Gospod.\nVes dan, vso noč angeli, varujte me!\n\nSonce kmalu bo zašlo,\nangeli bdijo nad menoj, Gospod.\nČuvaj me to noč, moj Bog,\nangeli varujte me!","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":8},{"number":9,"title":"Hvalnico pojem Bogu","body":"Hvalnico pojem Bogu","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":9},{"number":64,"title":"Če imate usta","body":"(D)    G                  A           D\nČe roke imate, bratu pomagajte,\nče ušesa imate, brata poslušajte,\nin če noge imate, k bratu pojdite,\nče imate usta, slavite Boga!\n\nČe imate usta, če imate usta\nče imate usta, slavite Boga!","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":10},{"number":11,"title":"Jezus ljubi vse otroke","body":"Jezus ljubi vse otroke","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":11},{"number":62,"title":"Gospod usmili se","body":"Gospod, usmili se,\nGospod, usmili se.   (2x)\n\nKristus, usmili se,\nKristus, usmili se.   (2x)\n\nGospod, usmili se,\nGospod, usmili se.   (2x)","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":12},{"number":13,"title":"Jezus oprosti mi","body":"Jezus oprosti mi","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":13},{"number":14,"title":"Kakor je bil ta kruh","body":"Kakor je bil ta kruh","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":14},{"number":76,"title":"Poslušajte vsi ljudje","body":"Poslušajte, vsi ljudje, sveti Jožef v mesto gre.\nSveti Jožef in Marija gresta v mesto Betlehem.   (2x)\n\nKo pa v mesto prideta, prenočišče iščeta.\nOj, ti mesto betlehemsko, da nas nočeš prenočit.   (2x)","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":15},{"number":68,"title":"Glej zvezdice Božje","body":"Glej, zvezdice božje migljajo lepo,\nodprto široko je sveto nebo.\n\nDuhovi nebeški se z raja vrste,\nprepevajo slavo, na zemljo hite.   2X","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":16},{"number":66,"title":"Tam stoji pa hlevček","body":"Tam stoji pa hlevček (2x)\nLepi hlevček Betlehem. (2x)\n\nNotri je Marija, detece povija,\nSveto dete Jezusa. (2x)\n\nTam hite pastirci, tam hite pastirci,\nv lepi hlevček Betlehem. (2x)","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":17},{"number":70,"title":"Sveta noč","body":"Sveta noč, blažena noč vse že spi, je polnoč,\nle devica z Jožefom tam, v hlevcu varje detece nam.\nspavaj dete sladko, spavaj dete sladko.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":18},{"number":19,"title":"Mlado še dekle","body":"Mlado še dekle","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":19},{"number":20,"title":"Mnogo poti","body":"Mnogo poti","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":20},{"number":16,"title":"Ko čutiš to","body":"Ko čutiš to, da tvoja pot\nje v tem, da bitje našel si,\nki se mu želiš darovat,\nga vedno prvi ljubil ti.\n\nLjubi ne čakaj, da ljubljen boš sam,\nnihče ti branit ne more.\nLjubi, kjer tema je, delal boš dan,\nLahko boš premikal gore. 2x","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":21},{"number":83,"title":"Ti naša mati ljubljena","body":"Ti naša Mati ljubljena, si od Boga izvoljena.\nTi polna vseh si milosti, zdaj k tebi prihitim.\n\nAve, ave, ave Marija, prosi, prosi, prosi za nas.\nAve, ave, ave Marija, prosi, prosi, prosi za nas\nBoga.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":22},{"number":96,"title":"Naj te pozdravim","body":"Naj te pozdravim Sveta Gospa\nin Kraljica nebeška, Mati si Božja.\nVedno ostaneš sveta Devica,\nsaj Oče nebeški te je blagoslovil.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":23},{"number":24,"title":"Naj bo lep ta dan","body":"Naj bo lep ta dan","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":24},{"number":25,"title":"Cvet dišeč","body":"Cvet dišeč","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":25},{"number":92,"title":"Mamica je kakor zarja","body":"Mamica je kakor zarja, zjutraj se smehlja,\nko se v postelji še dete s sanjami igra.\nin zato nikdar mamice ne dam,\neno le na svetu širnem mamico imam.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":26},{"number":27,"title":"O gospod studenec vse dobrote","body":"O gospod studenec vse dobrote","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":27},{"number":93,"title":"Aleluja (Jezus Kristus je naš Rešenik)","body":"Jezus Kristus je naš Rešenik\nJezus Kristus je vstal in živi,\ns svojim križem premagal je smrt, aleluja.\n\nAleluja (3x), aleluja (3x), aleluja (3x), aleluja.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":28},{"number":95,"title":"Jezus, hvala za sonce","body":"Jezus, hvala za sonce,\nJezus, hvala za sončno kremo,\nJezus, hvala za morski vonj po sončni kremi,\nHvala, hvala, hvala, hvala ti!\nHvala, hvala, hvala, hvala ti!\nVsak dan podarjaš svoje nam darove.","mode":"children","imageDataUrl":"data:image/jpeg;base64,","page":29}]};